package com.commercecore.shipping;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="shipment_tracking_events")public class ShipmentTrackingEvent{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="shipment_id",nullable=false)private Shipment shipment;@Enumerated(EnumType.STRING)@Column(name="tracking_status",nullable=false,length=24)private TrackingStatus status;@Column(length=160)private String location;@Column(length=500)private String note;@Column(name="occurred_at",nullable=false)private Instant occurredAt;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt;protected ShipmentTrackingEvent(){}public ShipmentTrackingEvent(Shipment s,TrackingStatus status,String location,String note,Instant occurred){shipment=s;this.status=status;this.location=optional(location,160);this.note=optional(note,500);occurredAt=occurred;}@PrePersist void create(){createdAt=Instant.now();}private static String optional(String s,int max){if(s==null||s.isBlank())return null;if(s.trim().length()>max)throw new IllegalArgumentException();return s.trim();}public UUID getId(){return id;}public TrackingStatus getStatus(){return status;}public String getLocation(){return location;}public String getNote(){return note;}public Instant getOccurredAt(){return occurredAt;}public Instant getCreatedAt(){return createdAt;}}
